using System.Net.Http.Headers;using System.Net.Http.Json;using NexaConnect.Infrastructure.Authentication;using NexaConnect.Infrastructure.Authorization;using NexaConnect.Services.Kitchen.Application.Tenant;
namespace NexaConnect.Services.Kitchen.Infrastructure;
public sealed class HttpKitchenTenantAuthorizer(IHttpClientFactory clients,IServiceWorkloadTokenProvider tokens,ProductAuthorizationClient authorization):IKitchenTenantAuthorizer
{
 public async Task<bool> HasBranchAccessAsync(Guid organizationId,Guid branchId,string permission,string authorizationHeader,CancellationToken cancellationToken)
 {if(organizationId==Guid.Empty||branchId==Guid.Empty||!AuthenticationHeaderValue.TryParse(authorizationHeader,out var customer))return false;using var access=new HttpRequestMessage(HttpMethod.Get,$"api/platform-directory/v1/organizations/{organizationId:D}/access");access.Headers.Authorization=customer;using var accessResponse=await clients.CreateClient("KitchenPlatformDirectory").SendAsync(access,cancellationToken);if(!accessResponse.IsSuccessStatusCode)return false;using var scopeRequest=new HttpRequestMessage(HttpMethod.Get,$"api/restaurant/v1/branches/{branchId:D}/authorization-scope");scopeRequest.Headers.Authorization=new AuthenticationHeaderValue("Bearer",await tokens.GetAsync(cancellationToken));using var scopeResponse=await clients.CreateClient("KitchenRestaurant").SendAsync(scopeRequest,cancellationToken);if(!scopeResponse.IsSuccessStatusCode)return false;var scope=await scopeResponse.Content.ReadFromJsonAsync<BranchScope>(cancellationToken:cancellationToken);return scope is not null&&scope.OrganizationId==organizationId&&scope.BranchId==branchId&&await authorization.IsGrantedAsync(organizationId,scope.RestaurantId,branchId,permission,authorizationHeader,cancellationToken);}
 private sealed record BranchScope(Guid OrganizationId,Guid RestaurantId,Guid BranchId);
}
